<?php
declare(strict_types=1);
require __DIR__ . '/../includes/db.php';
if(empty($_SESSION['blog_admin_id'])){header('Location: login.php');exit;}
if(($_SESSION['blog_admin_role']??'admin')!=='admin'){http_response_code(403);exit('Bạn không có quyền quản lý cộng tác viên.');}
if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(32));
$csrf=$_SESSION['csrf'];$error='';$notice='';
function ac_h($v):string{return htmlspecialchars((string)($v??''),ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!hash_equals($csrf,(string)($_POST['csrf']??''))){$error='Phiên quản trị hết hạn.';}
 else{$id=(int)($_POST['member_id']??0);$role=(string)($_POST['account_type']??'member');if($id<1||!in_array($role,['member','contributor'],true))$error='Dữ liệu phân quyền không hợp lệ.';else{try{$q=$pdo->prepare('UPDATE members SET account_type=? WHERE id=?');$q->execute([$role,$id]);$notice=$role==='contributor'?'Đã cấp quyền cộng tác viên.':'Đã gỡ quyền cộng tác viên.';}catch(Throwable $e){$error='Chưa cập nhật được. Hãy chạy database/moderation_staff.sql trước.';}}}
}
$search=trim((string)($_GET['q']??''));$filter=(string)($_GET['type']??'all');if(!in_array($filter,['all','contributor','member'],true))$filter='all';$where=[];$params=[];
if($filter!=='all'){$where[]='m.account_type=?';$params[]=$filter;}
if($search!==''){$where[]='(m.display_name LIKE ? OR m.email LIKE ? OR CAST(m.id AS CHAR)=?)';array_push($params,'%'.$search.'%','%'.$search.'%',$search);}
$clause=$where?' WHERE '.implode(' AND ',$where):'';
$count=$pdo->prepare('SELECT COUNT(*) FROM members m'.$clause);$count->execute($params);$total=(int)$count->fetchColumn();
$pageSize=20;$pages=max(1,(int)ceil($total/$pageSize));$page=max(1,min($pages,(int)($_GET['page']??1)));$offset=($page-1)*$pageSize;
$q=$pdo->prepare("SELECT m.id,m.display_name,m.email,m.is_active,m.account_type,m.created_at,(SELECT COUNT(*) FROM stories s WHERE s.member_id=m.id) AS story_count,(SELECT COUNT(*) FROM stories s WHERE s.member_id=m.id AND s.status='published') AS published_count FROM members m".$clause." ORDER BY (m.account_type='contributor') DESC,m.id DESC LIMIT ".$pageSize." OFFSET ".$offset);$q->execute($params);$items=$q->fetchAll();
$contributorsCount=(int)$pdo->query("SELECT COUNT(*) FROM members WHERE account_type='contributor'")->fetchColumn();
?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Quản lý CTV | Truyện Đêm CMS</title><link rel="stylesheet" href="../css/style.css"><link rel="stylesheet" href="../css/admin-white.css?v=20261114-white1"><link rel="stylesheet" href="../css/admin-cms.css?v=20261121-cms1"></head><body class="admin-theme"><?php include __DIR__.'/_nav.php';?><main class="admin-wrap"><section class="admin-panel admin-wide"><div class="admin-top"><div><h1>Quản lý cộng tác viên</h1><p>Cấp hoặc gỡ quyền CTV cho thành viên đã đăng ký.</p></div><strong class="staff-total"><?=$contributorsCount?> CTV</strong></div><?php if($notice):?><p class="admin-success"><?=ac_h($notice)?></p><?php endif;?><?php if($error):?><p class="admin-error"><?=ac_h($error)?></p><?php endif;?>
<form class="staff-filter" method="get"><input type="search" name="q" value="<?=ac_h($search)?>" placeholder="Tìm tên, email hoặc ID"><select name="type"><option value="all" <?=$filter==='all'?'selected':''?>>Tất cả thành viên</option><option value="contributor" <?=$filter==='contributor'?'selected':''?>>Đang là CTV</option><option value="member" <?=$filter==='member'?'selected':''?>>Chưa là CTV</option></select><button type="submit">Tìm kiếm</button></form>
<div class="staff-table-wrap"><table><thead><tr><th>Thành viên</th><th>Bài đã gửi</th><th>Đã xuất bản</th><th>Tham gia</th><th>Vai trò</th></tr></thead><tbody><?php foreach($items as $m):?><tr><td><strong><?=ac_h($m['display_name'])?></strong><small>#<?=(int)$m['id']?> · <?=ac_h($m['email'])?></small></td><td><?=(int)$m['story_count']?></td><td><?=(int)$m['published_count']?></td><td><?=ac_h(date('d/m/Y',strtotime($m['created_at'])))?></td><td><form method="post" class="staff-role-form"><input type="hidden" name="csrf" value="<?=ac_h($csrf)?>"><input type="hidden" name="member_id" value="<?=(int)$m['id']?>"><select name="account_type"><option value="member" <?=$m['account_type']==='member'?'selected':''?>>Thành viên</option><option value="contributor" <?=$m['account_type']==='contributor'?'selected':''?>>Cộng tác viên</option></select><button type="submit">Cập nhật</button></form></td></tr><?php endforeach;?><?php if(!$items):?><tr><td colspan="5">Không tìm thấy thành viên.</td></tr><?php endif;?></tbody></table></div><?php if($pages>1):?><nav class="story-pagination"><?php if($page>1):?><a href="?<?=http_build_query(['q'=>$search,'type'=>$filter,'page'=>$page-1])?>">← Trước</a><?php endif;?><strong><?=$page?> / <?=$pages?></strong><?php if($page<$pages):?><a href="?<?=http_build_query(['q'=>$search,'type'=>$filter,'page'=>$page+1])?>">Sau →</a><?php endif;?></nav><?php endif;?></section></main></body></html>